","64776":"\ufd08\ufd24","64777":"\ufd09\ufd25\ufd2d\ufd37","64778":"\ufd0a\ufd26\ufd2e\ufd38","64779":"\ufd0b\ufd27\ufd2f\ufd39","64781":"\ufd0d\ufd29","64782":"\ufd0e\ufd2a","64783":"\ufd0f\ufd2b","64784":"\ufd10\ufd2c","64849":"\ufd51\ufd52","64856":"\ufd58\ufd59","64863":"\ufd5f\ufd60","64866":"\ufd62\ufd63","64868":"\ufd64\ufd65","64870":"\ufd66\ufdc5","64871":"\ufd67\ufd68","64874":"\ufd6a\ufd6b","64876":"\ufd6c\ufd6d","64879":"\ufd6f\ufd70","64881":"\ufd71\ufd72","64885":"\ufd75\ufdc4","64886":"\ufd76\ufd77","64892":"\ufd7c\ufd7d","64894":"\ufd7e\ufdb4","64896":"\ufd80\ufdb5","64899":"\ufd83\ufd84","64901":"\ufd85\ufd86","64903":"\ufd87\ufd88","64919":"\ufd97\ufd98","64924":"\ufd9c\ufd9d","64952":"\ufdb8\ufdbd","64954":"\ufdba\ufdbc","64955":"\ufdbb\ufdc3","65269":"\ufef5\ufef6","65271":"\ufef7\ufef8","65273":"\ufef9\ufefa","65275":"\ufefb\ufefc"}$classes$::jsonb;
    result text := '^';
    i integer := 1;
    c text;
    escaped boolean;
    members text;
BEGIN
    WHILE i <= char_length(pattern) LOOP
        c := substr(pattern, i, 1);
        i := i + 1;
        escaped := false;
        IF c = chr(92) AND i <= char_length(pattern) THEN
            c := substr(pattern, i, 1);
            i := i + 1;
            escaped := true;
        END IF;
        IF NOT escaped AND c = '%' THEN
            result := result || '.*';
        ELSIF NOT escaped AND c = '_' THEN
            result := result || '.';
        ELSE
            members := classes ->> (keys ->> ascii(c)::text);
            IF members IS NULL THEN
                members := CASE WHEN c IN (chr(92), '[', ']', '-', '^')
                                THEN chr(92) || c ELSE c END;
            END IF;
            result := result || '[' || members || ']';
        END IF;
    END LOOP;
    RETURN result || '$';
END;
$function$;

-- SQL inlining lets PostgreSQL fold a constant/bound search pattern once and
-- run its native cached regexp engine against the original stored text.
CREATE FUNCTION submission_like(value text, pattern text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $function$
    SELECT value COLLATE "C" ~ submission_like_pattern(pattern) COLLATE "C"
$function$;

