    result text := '';
    cp integer;
    weight text;
    base integer;
BEGIN
    FOR i IN 1..char_length(value) LOOP
        cp := ascii(substr(value, i, 1));
        weight := weights ->> cp::text;
        IF weight IS NULL THEN
            IF cp > 65535 THEN
                weight := 'FFFD';
            ELSE
                base := CASE WHEN cp BETWEEN 13312 AND 19893 THEN 64384
                             WHEN cp BETWEEN 19968 AND 40869 THEN 64320
                             ELSE 64448 END;
                weight := lpad(to_hex(base + (cp >> 15)), 4, '0') ||
                          lpad(to_hex((cp & 32767) | 32768), 4, '0');
            END IF;
        END IF;
        result := result || weight;
    END LOOP;
    WHILE right(result, 4) = '0209' LOOP
        result := left(result, length(result) - 4);
    END LOOP;
    RETURN decode(result, 'hex');
END;
$function$;

CREATE FUNCTION submission_equal(left_value text, right_value text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $function$
    SELECT submission_text_key(left_value) = submission_text_key(right_value)
$function$;

