    result text := '';
    cp integer;
BEGIN
    FOR i IN 1..char_length(value) LOOP
        cp := ascii(substr(value, i, 1));
        result := result || COALESCE(weights ->> cp::text,
            CASE WHEN cp > 65535 THEN 'FFFD' ELSE lpad(to_hex(cp), 4, '0') END);
